document.querySelector(".query-footer").insertAdjacentHTML("beforeend",'<button id="cancel-search" class="secondary" hidden>검색 취소</button>');
document.querySelector("#search-results").insertAdjacentHTML("afterend",'<div class="inline-form" id="search-pages" hidden><button id="page-previous" class="secondary">← 이전</button><span id="page-description"></span><button id="page-next" class="secondary">다음 →</button></div><details><summary>최근 검색 작업</summary><div id="job-history"></div></details>');
document.querySelector('#language option[value="spl"]').textContent="SPL";
document.querySelector("#view-search .page-heading p:not(.eyebrow)").textContent="이벤트 검색·계산·통계·시간 분석을 하나의 파이프라인으로 실행합니다.";
document.querySelector(".query-footer span").textContent="search · eval · where · stats · timechart · streamstats · rex · spath";
document.querySelector("#view-rules form .muted").textContent="이벤트 또는 집계 결과를 조건으로 탐지합니다. 임계값은 결과 행 수입니다. 집계 값 임계값은 where로 지정하세요.";
document.querySelector('#rule-form label:has(input[name="threshold"])').firstChild.textContent="최소 결과 행 수";
document.querySelectorAll("#view-search details").forEach(d=>{if(d.querySelector("pre")){d.querySelector("pre").textContent='search severity=high | stats count by source | where count>=5\nsearch * | eval bytes=tonumber(raw.bytes) | timechart span=5m sum(bytes) AS traffic\nsearch * | rex "src=(?<src>[0-9.]+)" | stats count by src';d.querySelector("p").textContent="명령·옵션 지원 범위는 제품 README의 호환성 표를 참고하세요. 원시 SQL과 외부 파일 실행은 허용하지 않습니다.";}});
api("/api/bootstrap").then(s=>{document.querySelector(".auth-card small").textContent="Vatex xSERA XDR · "+s.version;document.querySelector("footer span:last-child").textContent="Version "+s.version;document.querySelector(".sidebar-foot small:last-child").textContent="Version "+s.version;}).catch(()=>{});

const sapientiaBaseView=view;
view=async function(name){await sapientiaBaseView(name);if(name==="account")await accountView();if(name==="cluster")await clusterView();if(name==="dashboards")await dashboardView();if(name==="search")await jobHistory();};
const sapientiaBaseEnter=enter;
enter=async function(){if(me.must_change){document.body.dataset.role=me.role;$("#auth").hidden=true;$("#shell").hidden=false;$("#identity").textContent=me.name+" / "+me.role;$("#tenant").textContent=me.tenant;await view("account");}else await sapientiaBaseEnter();};

let sapientiaJob=null,sapientiaOffset=0,sapientiaNext=null,sapientiaDashboards=[];
async function jobHistory(){const list=await api("/api/search/jobs");$("#job-history").innerHTML=table(["created","state","error","action"],list,{created:v=>escapeHtml(date(v)),action:(_,r)=>r.state==="done"?`<button data-job="${escapeHtml(r.id)}">결과 보기</button>`:""});}
async function showJobPage(offset){const result=await api(`/api/search/jobs/${encodeURIComponent(sapientiaJob)}/results?offset=${offset}&count=100`);sapientiaOffset=offset;sapientiaNext=result.next_offset;$("#search-results").innerHTML=table(result.columns,result.rows,{event_time:v=>escapeHtml(date(v)),_time:v=>escapeHtml(date(v)),severity:v=>`<span class="severity ${escapeHtml(v)}">${escapeHtml(v)}</span>`});$("#search-status").textContent=`${fmt(result.total_materialized)}개 결과 · ${result.elapsed_ms} ms${result.at_limit?" · 결과 한도 도달":""}`;$("#search-pages").hidden=!result.total_materialized;$("#page-description").textContent=`${offset+1}–${offset+result.page_returned} / ${result.total_materialized}`;$("#page-previous").disabled=offset===0;$("#page-next").disabled=sapientiaNext===null;}
$("#page-previous").onclick=()=>showJobPage(Math.max(0,sapientiaOffset-100)).catch(e=>notice(e.message));
$("#page-next").onclick=()=>showJobPage(sapientiaNext).catch(e=>notice(e.message));
$("#run-search").addEventListener("click",async event=>{event.stopImmediatePropagation();const button=event.currentTarget;button.disabled=true;notice("");$("#search-pages").hidden=true;$("#search-status").textContent="검색 작업 접수 중";try{const now=Date.now()/1000;const job=await post("/api/search/jobs",{language:$("#language").value,query:$("#query").value,earliest:now-Number($("#time-range").value),latest:now,limit:Number($("#result-limit").value)});sapientiaJob=job.id;$("#cancel-search").hidden=false;for(;;){const state=await api(`/api/search/jobs/${encodeURIComponent(job.id)}`);$("#search-status").textContent={queued:"대기열에서 실행 대기",running:"검색 실행 중",cancel_requested:"취소 요청 처리 중",cancelled:"검색이 취소되었습니다",failed:"검색 실패",done:"검색 완료"}[state.state]||state.state;if(state.state==="done"){await showJobPage(0);break;}if(["cancelled","failed"].includes(state.state)){if(state.error)notice(state.error);break;}await new Promise(resolve=>setTimeout(resolve,300));}await jobHistory();}catch(e){notice(e.message);$("#search-status").textContent="검색 실패";}finally{button.disabled=false;$("#cancel-search").hidden=true;}},true);
$("#cancel-search").onclick=()=>post(`/api/search/jobs/${encodeURIComponent(sapientiaJob)}/cancel`,{}).catch(e=>notice(e.message));
document.addEventListener("click",event=>{const button=event.target.closest("[data-job]");if(button){sapientiaJob=button.dataset.job;showJobPage(0).catch(e=>notice(e.message));}});

async function clusterView(){const h=await api("/api/health"),c=h.cluster;metrics("#cluster-metrics",[["배포 모드",c?"복제 클러스터":"독립 노드",c?.cluster_id||"로컬 영속 수집"],["저널 복제 수",c?fmt(c.replicas):"—","설정된 quorum 복제"],["적용 시퀀스",c?fmt(c.applied_sequence):"—",c?.node_id||"현재 노드"],["인덱싱 대기",fmt(h.pending),`${h.oldest_pending_seconds}초 대기`]]);$("#cluster-detail").innerHTML=c?`<h2>동기화 상태</h2><p>최근 재생: ${escapeHtml(date(c.last_sync))}</p><p>상태: ${escapeHtml(c.error||"현재 재생 오류 없음")}</p><p>저장 모드: 전체 사본</p><p>무결성 체크포인트: <code>${escapeHtml(c.digest)}</code></p>`:'<h2>독립 노드로 실행 중입니다.</h2><p>현재 프로세스에는 외부 복제 클러스터가 연결되어 있지 않습니다. 저널 복제를 구성하면 이 화면에 실제 복제 수와 적용 시퀀스가 표시됩니다.</p>';}
$("#cluster-refresh").onclick=()=>clusterView().catch(e=>notice(e.message));
async function accountView(){$("#rotation-required").hidden=!me.must_change;$("#mfa-card").hidden=!!me.must_change;$("#user-management").hidden=me.role!=="admin"||!!me.must_change;if(me.must_change)return;const m=await api("/api/me/mfa");$("#mfa-status").textContent=m.enabled?"인증 앱을 통한 2단계 인증이 활성화되어 있습니다.":"2단계 인증이 비활성화되어 있습니다.";$("#mfa-enroll-form").hidden=m.enabled;$("#mfa-disable-form").hidden=!m.enabled;if(me.role==="admin"){const list=await api("/api/users");$("#users-list").innerHTML=table(["name","role","disabled","mfa_enabled","action"],list,{disabled:v=>v?"중지":"활성",mfa_enabled:v=>v?"ON":"OFF",action:(_,r)=>`<button data-user-disable="${escapeHtml(r.name)}" data-role="${escapeHtml(r.role)}" data-disabled="${!r.disabled}">${r.disabled?"계정 활성화":"계정 중지"}</button>`});}}
$("#password-form").onsubmit=async event=>{event.preventDefault();try{await post("/api/me/password",Object.fromEntries(new FormData(event.target)));event.target.reset();await boot();}catch(e){notice(e.message);}};
$("#mfa-enroll-form").onsubmit=async event=>{event.preventDefault();try{const result=await post("/api/me/mfa/enroll",Object.fromEntries(new FormData(event.target)));event.target.reset();$("#mfa-secret").hidden=false;$("#mfa-secret").textContent="인증 앱에 다음 키를 직접 등록하세요. 10분 안에 확인해야 합니다.\n"+result.secret+"\n"+result.uri;$("#mfa-confirm-form").hidden=false;}catch(e){notice(e.message);}};
$("#mfa-confirm-form").onsubmit=async event=>{event.preventDefault();try{await post("/api/me/mfa/confirm",Object.fromEntries(new FormData(event.target)));event.target.reset();$("#mfa-secret").textContent="";$("#mfa-secret").hidden=true;await boot();}catch(e){notice(e.message);}};
$("#mfa-disable-form").onsubmit=async event=>{event.preventDefault();try{await post("/api/me/mfa/disable",Object.fromEntries(new FormData(event.target)));event.target.reset();await boot();}catch(e){notice(e.message);}};
$("#user-form").onsubmit=async event=>{event.preventDefault();try{await post("/api/users",Object.fromEntries(new FormData(event.target)));event.target.reset();await accountView();notice("사용자가 생성되었습니다. 첫 로그인에서 비밀번호를 변경해야 합니다.");}catch(e){notice(e.message);}};
document.addEventListener("click",async event=>{const b=event.target.closest("[data-user-disable]");if(!b)return;try{await post("/api/users/"+encodeURIComponent(b.dataset.userDisable),{role:b.dataset.role,disabled:b.dataset.disabled==="true"},"PATCH");await accountView();}catch(e){notice(e.message);}});
async function dashboardView(){sapientiaDashboards=await api("/api/dashboards");$("#dashboard-selector").innerHTML='<option value="">선택하세요</option>'+sapientiaDashboards.map(d=>`<option value="${escapeHtml(d.id)}">${escapeHtml(d.name)} · ${escapeHtml(d.owner)}</option>`).join("");$("#dashboard-editor").hidden=me.role==="viewer";}
$("#dashboard-form").onsubmit=async event=>{event.preventDefault();try{const d=Object.fromEntries(new FormData(event.target));const result=await post("/api/dashboards",{name:d.name,panels:JSON.parse(d.panels),shared:!!event.target.elements.shared.checked});await dashboardView();$("#dashboard-selector").value=result.id;notice("대시보드가 저장되었습니다.");}catch(e){notice(e.message);}};
$("#dashboard-run").onclick=async()=>{const d=sapientiaDashboards.find(v=>v.id===$("#dashboard-selector").value);if(!d)return;$("#dashboard-panels").innerHTML=d.panels.map((p,i)=>`<article><h2>${escapeHtml(p.title)}</h2><div id="dashboard-panel-${i}">검색 중...</div></article>`).join("");for(let i=0;i<d.panels.length;i++){const p=d.panels[i],target=$("#dashboard-panel-"+i);try{const r=await post("/api/search",p.query);if(p.display==="number")target.textContent=r.rows.length?String(Object.values(r.rows[0]).at(-1)):"0";else if(p.display==="bar"){const max=Math.max(1,...r.rows.map(v=>Number(Object.values(v).at(-1))||0));target.innerHTML=r.rows.slice(0,30).map(v=>{const a=Object.values(v),n=Number(a.at(-1))||0;return `<div class="source-row"><div><span>${escapeHtml(a[0])}</span><span>${fmt(n)}</span></div><meter min="0" max="${max}" value="${n}"></meter></div>`;}).join("");}else target.innerHTML=table(r.columns,r.rows);}catch(e){target.textContent=e.message;}}};

// Bounded engineering and investigation workflows. Nothing is saved or enabled
// until the operator submits a form; all server responses are escaped or text.
document.addEventListener("DOMContentLoaded", () => {
  const tabs = [["content", "탐지 콘텐츠", "rules"], ["entities", "엔터티 · 행위", "findings"], ["quality", "수집 품질", "sources"], ["casework", "조사 · 플레이북", "findings"]];
  for (const [name, title, icon] of tabs) {
    labels[name] = title;
    horizonNames[name] = title;
    const button = document.createElement("button");
    button.dataset.view = name;
    button.className = "analyst-only";
    button.innerHTML = horizonSvg(icon) + `<span>${escapeHtml(title)}</span>`;
    horizonOperations.querySelector("div").append(button);
  }
  const css = document.createElement("style");
  css.textContent = ".enterprise-output{max-height:420px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere}.enterprise-view article{margin-bottom:22px}.enterprise-view textarea{font-family:Consolas,monospace}.enterprise-view .form-grid{align-items:end}.operations-popover{max-height:calc(100vh - 130px);overflow-y:auto}";
  document.head.append(css);
  const heading = (kicker, title, description, refresh) => `<div class="page-heading"><div><p class="eyebrow">${kicker}</p><h1>${title}</h1><p>${description}</p></div><button class="secondary" id="${refresh}">↻ 새로고침</button></div>`;
  document.querySelector("main").insertAdjacentHTML("beforeend", `
  <section id="view-content" class="view enterprise-view" hidden>
    ${heading("DETECTION ENGINEERING", "검증한 콘텐츠를 배포하다", "불변 버전과 양성·음성 테스트, 실제 소스의 필드 조건을 확인합니다.", "content-refresh")}
    <article><h2>테넌트 콘텐츠 패키지</h2><div id="content-list"></div></article>
    <article><h2>패키지 작성 · 가져오기</h2><p class="muted">현재 범위는 하나의 정확한 인덱스 안에서 실행하는 순서형 상관 정책입니다. 모든 규칙에 양성·음성 fixture가 필요합니다. 예제는 비활성 상태이며 운영 데이터를 수집하지 않습니다.</p>
      <div class="intelligence-actions"><button id="content-sample" class="secondary">비활성 예제 불러오기</button><label>JSON 파일<input id="content-file" type="file" accept=".json,application/json"></label></div>
      <form id="content-form"><label>패키지 JSON<textarea id="content-body" rows="18" required spellcheck="false"></textarea></label><label>현재 패키지 버전 · 새 패키지는 0<input id="content-version" type="number" min="0" value="0" required></label><div class="intelligence-actions"><button id="content-dry" type="button" class="secondary">변경 없이 검사</button><button class="primary">초안 버전 저장</button></div></form>
    </article>
    <article><h2>저장된 버전 검증 · 배포</h2><p id="content-selected">먼저 패키지를 선택하거나 저장하세요.</p><label>대상 revision<select id="content-revision"><option value="">선택하세요</option></select></label><div class="intelligence-actions"><button id="content-test" class="secondary" disabled>Fixture 테스트</button><button id="content-coverage" class="secondary" disabled>최근 소스 조건 확인</button><button id="content-export" class="secondary" disabled>선택 버전 내보내기</button><button id="content-publish" class="primary admin-only" disabled>선택 버전 배포</button><button id="content-rollback" class="secondary admin-only" disabled>이전 활성 버전으로 롤백</button></div><p class="muted">배포는 관리자만 가능합니다. 같은 revision의 테스트 통과와 최근 24시간의 필수 필드 존재가 필요합니다. 필드 존재는 전체 공격 탐지 효과를 보장하지 않습니다. 선택한 정의의 enabled 값을 확인하세요.</p><pre class="enterprise-output" id="content-result" role="status"></pre></article>
    <article><h2>Sigma JSON 부분집합 미리보기</h2><p>필드와 logsource 기준을 명시적으로 매핑하세요. 목록·와일드카드·집계·correlation·n-of 조건은 오류로 거부합니다. 결과는 검색용이며 상관 정책으로 자동 배포하지 않습니다.</p><form id="sigma-form"><label>규칙과 필드/소스 매핑<textarea id="sigma-body" rows="12" required spellcheck="false"></textarea></label><button class="secondary">지원 의미 검증 · 검색 생성</button></form><pre id="sigma-result" class="enterprise-output"></pre><button id="sigma-open-search" class="secondary" disabled>생성 쿼리를 로그 탐색에서 열기</button></article>
  </section>
  <section id="view-entities" class="view enterprise-view" hidden>
    ${heading("ENTITY CONTEXT", "같은 대상을, 같은 맥락으로", "직접 확인한 별칭과 자산 중요도, 실제 이벤트의 관찰 관계를 관리합니다.", "entities-refresh")}
    <article><h2>엔터티 인벤토리</h2><div id="inventory-list"></div></article>
    <article><h2>명시적 별칭 등록</h2><p class="muted">별칭의 동일성을 운영자가 확인해야 합니다. 관계는 같은 이벤트의 동시 관찰이며 통신 방향이나 공격자 귀속을 추론하지 않습니다.</p><form id="entity-form"><div class="form-grid"><label>종류<select id="entity-kind"><option>user</option><option>host</option><option>ip</option><option>device</option></select></label><label>이름<input id="entity-name" maxlength="256" required></label><label>정확한 인덱스 · 쉼표 구분<input id="entity-indexes" value="main" required></label><label>중요도 1..5<input id="entity-criticality" type="number" min="1" max="5" value="3" required></label></div><label>태그 · 쉼표 구분<input id="entity-tags"></label><label>별칭 JSON<textarea id="entity-aliases" rows="4" required spellcheck="false">[{"type":"username","value":"example-user"}]</textarea></label><div class="intelligence-actions"><button class="primary">엔터티 저장</button><button id="entity-new" type="button" class="secondary">새 엔터티</button></div></form><p id="entity-selected" class="muted">새 엔터티</p></article>
    <article><h2>근거 타임라인 · 동시 관찰 그래프</h2><div class="intelligence-actions"><label>조회 범위<select id="entity-window"><option value="3600">최근 1시간</option><option value="86400" selected>최근 24시간</option><option value="604800">최근 7일</option></select></label><button id="entity-graph" class="secondary">관찰 관계 조회</button></div><div id="entity-evidence"></div></article>
    <article><h2>행위 baseline</h2><p>명시한 기간의 버킷별 건수·표준편차, 알려진 호스트, UTC 업무 시간으로 비교합니다. 학습 데이터와 평가 기간을 분리하세요. peer 학습·상용 UEBA 완전 호환·자동 사건 생성을 제공하지 않습니다.</p><div id="baseline-list"></div><form id="baseline-form"><label>학습 정의 JSON · epoch 경계 정렬 필요<textarea id="baseline-body" rows="12" required spellcheck="false"></textarea></label><button class="primary">선택 기간으로 baseline 학습</button></form><form id="baseline-evaluate-form"><div class="form-grid"><label>저장된 baseline<select id="baseline-selector" required><option value="">선택하세요</option></select></label><label>평가 시작 epoch<input id="baseline-start" type="number" required></label><label>평가 종료 epoch<input id="baseline-end" type="number" required></label></div><button class="secondary">분리된 기간 평가</button></form><pre id="baseline-result" class="enterprise-output" role="status"></pre><div id="baseline-runs"></div></article>
  </section>
  <section id="view-quality" class="view enterprise-view" hidden>
    ${heading("COLLECTION QUALITY", "수집의 공백을 확인하다", "원시 JSON 매핑, 필드 누락, 격리와 소스 지연을 구분합니다.", "quality-refresh")}
    <article><h2>버전별 JSON 매핑 정책</h2><p>정확한 source에 적용하는 제한된 JSON 필드 매핑입니다. 임의 코드·정규식 vendor 파서가 아닙니다. 미리보기는 저장하지 않습니다. raw.parsed.password만 마스킹하면 같은 값이 포함된 원래 message는 남습니다. 원문 복사본도 제거하려면 message를 별도로 지정하세요. 정책 관리는 테넌트 전체 인덱스 권한이 필요합니다.</p><div id="parser-list"></div><form id="parser-form"><div class="form-grid"><label>정책 이름<input id="parser-name" value="example-json" maxlength="64" required></label><label>현재 버전<input id="parser-version" type="number" min="0" value="0" required></label></div><label>정의<textarea id="parser-body" rows="10" required spellcheck="false"></textarea></label><label>검증할 샘플 이벤트<textarea id="parser-sample" rows="6" required spellcheck="false"></textarea></label><div class="intelligence-actions"><button type="button" id="parser-preview" class="secondary">변경 없이 샘플 확인</button><button class="primary admin-only">정책 저장</button><button id="parser-new" type="button" class="secondary">새 비활성 정책</button></div></form><pre id="parser-result" class="enterprise-output" role="status"></pre></article>
    <article><h2>소스 침묵 · 필드 품질 · 도착 지연</h2><div id="monitor-list"></div><form id="monitor-form"><label>모니터와 버전 JSON<textarea id="monitor-body" rows="11" required spellcheck="false"></textarea></label><div class="intelligence-actions"><button class="primary">모니터 저장</button><button type="button" id="monitor-new" class="secondary">새 비활성 모니터</button></div></form><pre id="monitor-result" class="enterprise-output" role="status"></pre><p class="muted">운영 품질 측정입니다. 늦게 수신한 이벤트의 탐지 창을 자동 재평가하는 기능과는 별개입니다.</p></article>
    <article><h2>격리한 이벤트</h2><p>현재 접근할 수 있는 인덱스만 표시합니다. 정책을 수정하고 샘플을 확인한 뒤 관리자가 선택한 event_id를 다시 대기열에 넣습니다. 재처리 수락은 즉시 검색 가능함을 뜻하지 않습니다.</p><div id="quarantine-list"></div><div class="intelligence-actions"><button id="quarantine-first" class="secondary">첫 페이지</button><button id="quarantine-next" class="secondary" disabled>다음 페이지</button></div><pre id="quarantine-inspect" class="enterprise-output"></pre><form id="quarantine-form" class="admin-only"><label>재처리할 event_id JSON 배열<textarea id="quarantine-ids" rows="3" required spellcheck="false">[]</textarea></label><button class="secondary">선택 이벤트 재처리</button></form><pre id="quarantine-result" class="enterprise-output" role="status"></pre></article>
  </section>
  <section id="view-casework" class="view enterprise-view" hidden>
    ${heading("INVESTIGATION & APPROVAL", "조사의 근거와 다음 행동", "사건 업무·필수 작업·북마크와 독립 승인 플레이북을 연결합니다.", "casework-refresh")}
    <article><label>조사할 사건<select id="case-selector"><option value="">선택하세요</option></select></label><p id="case-heading">사건을 선택하세요.</p><div id="case-evidence-summary"></div></article>
    <article id="case-workspace" hidden><h2>사건 업무</h2><form id="case-metadata-form"><div class="form-grid"><label>우선순위<select id="case-priority"><option>medium</option><option>low</option><option>high</option><option>critical</option></select></label><label>기한 · 로컬 시각<input id="case-due" type="datetime-local"></label><label>태그 · 쉼표 구분<input id="case-tags"></label></div><button class="secondary">업무 정보 저장</button></form><div class="grid-two"><form id="case-note-form"><h3>조사 메모</h3><label>메모<textarea id="case-note" rows="4" maxlength="8000" required></textarea></label><button class="primary">메모 추가</button></form><form id="case-task-form"><h3>조사 작업</h3><label>작업 이름<input id="case-task-title" maxlength="200" required></label><label>담당자 · 현행 테넌트 분석가<input id="case-task-assignee" maxlength="64"></label><label class="check"><input id="case-task-mandatory" type="checkbox"> 완료 전 사건 종료 금지</label><button class="secondary">작업 추가</button></form></div><div id="case-tasks"></div><div id="case-notes"></div><form id="case-bookmark-form"><h3>이벤트 북마크</h3><div class="form-grid"><label>event_id<input id="case-event-id" maxlength="256" required></label><label>표시 이름<input id="case-bookmark-label" maxlength="200" required></label></div><button class="secondary">근거 북마크 저장</button></form><div id="case-bookmarks"></div><div class="intelligence-actions"><button id="case-export" class="secondary">사건 JSON 내보내기</button><button id="case-open-evidence" class="secondary">상관 근거 열기</button></div><pre id="case-result" class="enterprise-output" role="status"></pre></article>
    <article><h2>승인 기반 플레이북</h2><p>수동 시작은 승인 대기 상태를 만듭니다. 요청자와 다른 현행 분석가/관리자가 고정된 실행 내용을 검토하고 승인해야 합니다. 외부 webhook은 서버에서 미리 허용한 목적지만 사용하며 기본 구성은 비활성입니다. 모든 외부 서비스의 exactly-once를 보장하지 않습니다.</p><div id="playbook-list"></div><form id="playbook-form"><label>정의와 버전 JSON<textarea id="playbook-body" rows="10" required spellcheck="false"></textarea></label><div class="intelligence-actions"><button class="primary">플레이북 정의 저장</button><button id="playbook-new" type="button" class="secondary">새 정의</button></div></form><form id="playbook-start-form"><label>저장된 플레이북<select id="playbook-selector" required><option value="">선택하세요</option></select></label><button class="secondary">선택 사건에 실행 요청 · 승인 대기</button></form><div id="playbook-runs"></div><article id="playbook-review" hidden><h3>고정된 실행 내용 검토</h3><pre id="playbook-run-detail" class="enterprise-output"></pre><div class="intelligence-actions"><button id="playbook-approve" class="primary">검토한 실행 승인</button><button id="playbook-cancel" class="secondary">실행 취소 요청</button><button id="playbook-run-refresh" class="secondary">실행 상태 새로고침</button></div></article><pre id="playbook-result" class="enterprise-output" role="status"></pre></article>
  </section>`);

  let selectedContent = null, selectedEntity = null, selectedMonitor = null, selectedCase = null, selectedPlaybook = null, selectedRun = null, sigmaQuery = null;
  let entityRows = [], monitorRows = [], parserRows = [], quarantineRows = [], taskRows = [], nextQuarantine = null, baselineRows = [];
  const text = (selector, value) => { $(selector).textContent = typeof value === "string" ? value : JSON.stringify(value, null, 2); };
  const parse = selector => JSON.parse($(selector).value);
  const csv = selector => $(selector).value.split(",").map(x => x.trim()).filter(Boolean);
  const enc = encodeURIComponent;
  const download = (value, name) => { const url = URL.createObjectURL(new Blob([JSON.stringify(value, null, 2)], {type: "application/json"})); const link = document.createElement("a"); link.href = url; link.download = name; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); };
  const on = (id, fn) => { $(id).onclick = async event => { const button = event.currentTarget; const was = button.disabled; button.disabled = true; try { await fn(event); } catch (error) { notice(error.message); } finally { button.disabled = was; if (button.id === "quarantine-next") button.disabled = nextQuarantine === null; if (button.id === "playbook-approve") button.disabled = !selectedRun || selectedRun.state !== "pending_approval" || selectedRun.requested_by === me?.name; if (button.id === "playbook-cancel") button.disabled = !selectedRun || ["completed", "cancelled", "failed", "unknown"].includes(selectedRun.state); } }; };
  const submit = (id, fn) => { $(id).onsubmit = async event => { event.preventDefault(); const button = event.target.querySelector('button[type="submit"],button:not([type])'); if (button) button.disabled = true; try { await fn(event.target); } catch (error) { notice(error.message); } finally { if (button) button.disabled = false; } }; };
  const receipt = (form, value) => { const serialized = JSON.stringify(value); if (form.dataset.actionBody !== serialized) { form.dataset.actionBody = serialized; form.dataset.requestId = crypto.randomUUID(); } return form.dataset.requestId; };
  const finishReceipt = form => { delete form.dataset.actionBody; delete form.dataset.requestId; };
  const authTab = () => { if (!me || me.role === "viewer") throw Error("분석가 또는 관리자 권한이 필요합니다."); };
  let enterpriseIdentity = null;
  function clearEnterprise() {
    selectedContent = selectedEntity = selectedMonitor = selectedCase = selectedPlaybook = selectedRun = sigmaQuery = null;
    entityRows = monitorRows = parserRows = quarantineRows = taskRows = baselineRows = [];
    nextQuarantine = null;
    for (const form of document.querySelectorAll(".enterprise-view form")) { form.reset(); finishReceipt(form); }
    for (const output of document.querySelectorAll(".enterprise-view pre")) output.textContent = "";
    for (const id of ["content-list", "inventory-list", "entity-evidence", "baseline-list", "baseline-runs", "parser-list", "monitor-list", "quarantine-list", "case-tasks", "case-notes", "case-bookmarks", "playbook-list", "playbook-runs", "case-evidence-summary"]) $("#" + id).replaceChildren();
    for (const id of ["case-selector", "playbook-selector", "baseline-selector"]) $("#" + id).innerHTML = '<option value="">선택하세요</option>';
    $("#case-workspace").hidden = $("#playbook-review").hidden = true;
    $("#sigma-open-search").disabled = $("#quarantine-next").disabled = true;
    $("#sigma-body").value = $("#baseline-body").value = "";
    text("#case-heading", "사건을 선택하세요.");
    newContent(); newEntity(); parserSample(); monitorSample(); newPlaybook();
  }
  const enterpriseBaseEnter = enter;
  enter = async function() { const identity = JSON.stringify([me?.name, me?.tenant, me?.role, me?.csrf]); if (identity !== enterpriseIdentity) { clearEnterprise(); enterpriseIdentity = identity; } return enterpriseBaseEnter(); };
  const enterpriseBaseShowAuth = showAuth;
  showAuth = function() { clearEnterprise(); enterpriseIdentity = null; return enterpriseBaseShowAuth(); };
  const originalView = view;
  view = async function(name) { if (tabs.some(t => t[0] === name)) authTab(); await originalView(name); if (name === "content") await contentView(); if (name === "entities") await entitiesView(); if (name === "quality") await qualityView(); if (name === "casework") await caseworkView(); };

  function contentSample() {
    const end = Math.floor(Date.now() / 1000);
    const event = (action, at) => ({event_time: at, source: "example-auth", sourcetype: "example_auth", raw: {user: "example-user", action}});
    return {schema_version: 1, name: "example-auth-sequence", title: "인증 실패 후 성공 · 비활성 예제", prerequisites: {indexes: ["main"], sources: [{category: "authentication", sourcetypes: ["example_auth"], required_fields: ["raw.security.user", "raw.security.action"]}]}, rules: [{key: "failure-success", policy: {name: "인증 실패 후 성공", entity_field: "raw.security.user", window: 300, interval: 30, enabled: false, mitre: ["T1078"], steps: [{name: "실패", filters: [{field: "raw.action", op: "eq", value: "login_failed"}]}, {name: "성공", filters: [{field: "raw.action", op: "eq", value: "login_success"}]}]}}], fixtures: [{name: "positive", end, events: [event("login_failed", end - 30), event("login_success", end - 20)], expect: {"failure-success": ["example-user"]}}, {name: "negative", end, events: [event("login_success", end - 30), event("login_failed", end - 20)], expect: {"failure-success": []}}]};
  }
  function newContent() { selectedContent = null; $("#content-body").value = JSON.stringify(contentSample(), null, 2); $("#content-version").value = 0; text("#content-selected", "새 초안 · 예제의 enabled=false를 유지했습니다."); $("#content-revision").innerHTML = '<option value="">저장 후 선택</option>'; for (const id of ["test", "coverage", "export", "publish", "rollback"]) $("#content-" + id).disabled = true; }
  async function contentView() { const rows = await api("/api/content/packages"); $("#content-list").innerHTML = table(["name", "title", "version", "rule_count", "active_revision", "action"], rows, {active_revision: value => escapeHtml(value ? value.slice(0, 16) : "미배포"), action: (_, row) => `<button data-content-name="${escapeHtml(row.name)}">버전 열기</button>`}); if (!$("#content-body").value) newContent(); if (!$("#sigma-body").value) $("#sigma-body").value = JSON.stringify({rule: {title: "PowerShell 명령 예제", logsource: {category: "process_creation"}, detection: {selection: {"CommandLine|contains": "powershell"}, condition: "selection"}}, field_mapping: {CommandLine: "raw.command"}, logsource_mapping: {category: {field: "sourcetype", value: "sysmon_process"}}}, null, 2); }
  async function openContent(name, revision) { const item = await api(`/api/content/packages/${enc(name)}${revision ? "?revision=" + enc(revision) : ""}`); selectedContent = item; $("#content-body").value = JSON.stringify(item.payload, null, 2); $("#content-version").value = item.version; $("#content-revision").innerHTML = item.history.map(row => `<option value="${escapeHtml(row.revision)}" ${row.revision === item.revision ? "selected" : ""}>${escapeHtml(row.revision.slice(0, 16))} · ${escapeHtml(date(row.created))}${row.revision === item.active_revision ? " · 활성" : ""}</option>`).join(""); text("#content-selected", `${item.name} · ${item.state} · revision ${item.revision} · 현재 활성 ${item.active_revision || "없음"}`); for (const id of ["test", "coverage", "export", "publish", "rollback"]) $("#content-" + id).disabled = false; text("#content-result", {test: item.test, rollouts: item.rollouts}); }
  on("#content-refresh", contentView); on("#content-sample", newContent);
  $("#content-file").onchange = async event => { try { const file = event.target.files[0]; if (!file) return; if (file.size > 1024 * 1024 + 4096) throw Error("패키지 파일은 약 1 MiB 이하여야 합니다."); const value = JSON.parse(await file.text()); newContent(); $("#content-body").value = JSON.stringify(value.package || value, null, 2); text("#content-selected", "파일을 편집기에 불러왔습니다. 저장하지 않았습니다. 기존 이름이면 목록에서 현재 버전을 먼저 확인하세요."); } catch (error) { notice(error.message); } finally { event.target.value = ""; } };
  on("#content-dry", async () => text("#content-result", await post("/api/content/dry-run", parse("#content-body"))));
  submit("#content-form", async () => { const result = await post("/api/content/packages", {package: parse("#content-body"), expected_version: Number($("#content-version").value)}); await contentView(); await openContent(result.name, result.revision); notice("불변 초안 revision을 저장했습니다. 아직 배포하지 않았습니다."); });
  $("#content-revision").onchange = () => { if (selectedContent) openContent(selectedContent.name, $("#content-revision").value).catch(error => notice(error.message)); };
  const selected = () => { if (!selectedContent) throw Error("저장된 패키지 버전을 먼저 선택하세요."); return selectedContent; };
  on("#content-test", async () => { const item = selected(); text("#content-result", await post(`/api/content/packages/${enc(item.name)}/test`, {revision: item.revision})); });
  on("#content-coverage", async () => { const item = selected(); text("#content-result", await api(`/api/content/packages/${enc(item.name)}/coverage?revision=${enc(item.revision)}`)); });
  on("#content-export", async () => { const item = selected(); download(await api(`/api/content/packages/${enc(item.name)}/export?revision=${enc(item.revision)}`), `${item.name}-${item.revision.slice(0, 12)}.json`); });
  for (const action of ["publish", "rollback"]) on("#content-" + action, async () => { const item = selected(); const result = await post(`/api/content/packages/${enc(item.name)}/${action}`, {revision: item.revision, expected_active: item.active_revision}); await contentView(); await openContent(item.name, item.revision); text("#content-result", result); notice(action === "publish" ? "선택한 정책 정의를 원자적으로 배포했습니다." : "이전에 활성화한 정책 정의로 롤백했습니다."); });
  submit("#sigma-form", async () => { const result = await post("/api/content/sigma/preview", parse("#sigma-body")); sigmaQuery = result.query; text("#sigma-result", result); $("#sigma-open-search").disabled = false; });
  on("#sigma-open-search", async () => { if (!sigmaQuery) return; await view("search"); $("#language").value = "spl"; $("#query").value = sigmaQuery.query; notice("생성한 쿼리를 열었습니다. 시간 범위를 확인한 뒤 검색을 실행하세요."); });

  function newEntity() { selectedEntity = null; $("#entity-form").reset(); $("#entity-indexes").value = "main"; text("#entity-selected", "새 엔터티 · 별칭의 동일성을 직접 확인하세요."); }
  async function entitiesView() { entityRows = await api("/api/entities"); $("#inventory-list").innerHTML = table(["name", "kind", "indexes", "criticality", "aliases", "action"], entityRows, {action: (_, row) => `<button data-entity-edit="${escapeHtml(row.id)}">편집</button> <button data-entity-timeline="${escapeHtml(row.id)}">근거</button>`}); const [baselines, runs] = await Promise.all([api("/api/behavior/baselines"), api("/api/behavior/runs")]); baselineRows = baselines; $("#baseline-list").innerHTML = table(["name", "revision", "summary", "action"], baselines, {action: (_, row) => `<button data-baseline="${escapeHtml(row.id)}">저장된 모델 확인</button>`}); const prior = $("#baseline-selector").value; $("#baseline-selector").innerHTML = '<option value="">선택하세요</option>' + baselines.map(row => `<option value="${escapeHtml(row.id)}">${escapeHtml(row.name)} · revision ${row.revision}</option>`).join(""); if (baselines.some(row => row.id === prior)) $("#baseline-selector").value = prior; $("#baseline-runs").innerHTML = table(["created", "baseline_id", "action"], runs, {created: value => escapeHtml(date(value)), action: (_, row) => `<button data-behavior-run="${escapeHtml(row.id)}">평가 결과 열기</button>`}); if (!$("#baseline-body").value) { const end = Math.floor(Date.now() / 3600000) * 3600 - 86400; $("#baseline-body").value = JSON.stringify({name: "사용자 활동 비교", entity_field: "raw.security.user", indexes: ["main"], start: end - 604800, end, bucket_seconds: 3600, min_samples: 20, min_buckets: 7, z_threshold: 3, novelty_min_events: 1, business_hours_utc: {start: 0, end: 9, weekdays: [0, 1, 2, 3, 4]}}, null, 2); $("#baseline-start").value = end; $("#baseline-end").value = end + 86400; } }
  const entityRange = () => { const end = Date.now() / 1000; return new URLSearchParams({start: end - Number($("#entity-window").value), end, limit: 100}); };
  async function entityTimeline(id) { const result = await api(`/api/entities/${enc(id)}/timeline?${entityRange()}`); $("#entity-evidence").innerHTML = `<h3>${escapeHtml(result.entity.name)} · ${fmt(result.total)}개 이벤트${result.truncated ? " · 표시 한도 도달" : ""}</h3>` + table(["event_time", "event_id", "index_name", "source", "host", "message"], result.events, {event_time: value => escapeHtml(date(value))}); }
  on("#entities-refresh", entitiesView); on("#entity-new", newEntity);
  submit("#entity-form", async () => { const body = {kind: $("#entity-kind").value, name: $("#entity-name").value, indexes: csv("#entity-indexes"), criticality: Number($("#entity-criticality").value), tags: csv("#entity-tags"), aliases: parse("#entity-aliases"), version: selectedEntity?.version || 0}; const value = await post("/api/entities" + (selectedEntity ? "/" + enc(selectedEntity.id) : ""), body, selectedEntity ? "PUT" : "POST"); selectedEntity = value; text("#entity-selected", `${value.name} · version ${value.version}`); await entitiesView(); notice("명시적 별칭과 중요도를 저장했습니다."); });
  on("#entity-graph", async () => { const result = await api("/api/entities/graph?" + entityRange()); $("#entity-evidence").innerHTML = `<h3>이벤트의 동시 관찰 관계</h3><p>관찰 근거를 가진 관계입니다. 네트워크 흐름·공격 귀속을 의미하지 않습니다.</p><pre class="enterprise-output">${escapeHtml(JSON.stringify(result, null, 2))}</pre>`; });
  submit("#baseline-form", async () => { const result = await post("/api/behavior/baselines", parse("#baseline-body")); text("#baseline-result", result); await entitiesView(); $("#baseline-selector").value = result.id; notice("명시한 학습 창의 snapshot을 저장했습니다. 탐지를 자동 활성화하지 않습니다."); });
  submit("#baseline-evaluate-form", async () => { const id = $("#baseline-selector").value; text("#baseline-result", await post(`/api/behavior/baselines/${enc(id)}/evaluate`, {start: Number($("#baseline-start").value), end: Number($("#baseline-end").value)})); await entitiesView(); });
  $("#baseline-selector").onchange = () => { const row = baselineRows.find(item => item.id === $("#baseline-selector").value); if (row) { $("#baseline-start").value = row.definition.end; $("#baseline-end").value = row.definition.end + row.definition.bucket_seconds * 24; } };

  function parserSample() { $("#parser-name").value = "example-json"; $("#parser-version").value = 0; $("#parser-body").value = JSON.stringify({source: "example-json", sourcetype: "json", route_index: "main", mappings: {"raw.user": "raw.parsed.user"}, redact_fields: ["raw.parsed.password", "message"], required_fields: ["raw.user"], decode_message_json: true, on_failure: "quarantine", enabled: false}, null, 2); $("#parser-sample").value = JSON.stringify({source: "example-json", sourcetype: "json", message: '{"user":"example-user"}', raw: {}}, null, 2); }
  function monitorSample() { selectedMonitor = null; $("#monitor-body").value = JSON.stringify({version: 0, definition: {name: "예제 소스 품질 · 비활성", source: "example-json", indexes: ["main"], required_fields: ["raw.security.user"], max_silence: 300, max_lag: 300, window: 3600, interval: 60, enabled: false}}, null, 2); }
  async function qualityView() { const outcomes = await Promise.allSettled([api("/api/parsers"), api("/api/source-monitors"), loadQuarantine(0)]); if (outcomes[0].status === "fulfilled") { parserRows = outcomes[0].value; $("#parser-list").innerHTML = table(["name", "source", "version", "enabled", "action"], parserRows, {action: (_, row) => `<button data-parser="${escapeHtml(row.name)}">정의 열기</button>`}); } else text("#parser-list", outcomes[0].reason.message); if (outcomes[1].status === "fulfilled") { monitorRows = outcomes[1].value; $("#monitor-list").innerHTML = table(["name", "version", "enabled", "last_run", "result", "action"], monitorRows, {last_run: value => escapeHtml(date(value)), action: (_, row) => `<button data-monitor="${escapeHtml(row.id)}">편집</button> <button data-monitor-evaluate="${escapeHtml(row.id)}">현재 상태 측정</button>`}); } else text("#monitor-list", outcomes[1].reason.message); if (outcomes[2].status === "rejected") text("#quarantine-list", outcomes[2].reason.message); if (!$("#parser-body").value) parserSample(); if (!$("#monitor-body").value) monitorSample(); }
  async function loadQuarantine(offset) { const result = await api(`/api/quarantine?offset=${offset}&count=10`); quarantineRows = result.rows; nextQuarantine = result.next_offset; $("#quarantine-next").disabled = nextQuarantine === null; $("#quarantine-list").innerHTML = `<p>총 ${fmt(result.total_count)}개 · offset ${result.offset}</p>` + table(["event_id", "index_name", "source", "policy_name", "policy_version", "reason", "attempts", "action"], result.rows, {action: (_, row) => `<button data-quarantine="${escapeHtml(row.event_id)}">격리 내용</button>`}); }
  on("#quality-refresh", qualityView); on("#parser-new", parserSample); on("#monitor-new", monitorSample);
  on("#parser-preview", async () => text("#parser-result", await post("/api/parsers/preview", {definition: parse("#parser-body"), event: parse("#parser-sample")})));
  submit("#parser-form", async () => { const result = await post(`/api/parsers/${enc($("#parser-name").value)}`, {version: Number($("#parser-version").value), definition: parse("#parser-body")}, "PUT"); $("#parser-version").value = result.version; text("#parser-result", result); await qualityView(); notice("정의를 저장했습니다. enabled 값에 따라 적용됩니다."); });
  submit("#monitor-form", async () => { const result = await post("/api/source-monitors" + (selectedMonitor ? "/" + enc(selectedMonitor.id) : ""), parse("#monitor-body"), selectedMonitor ? "PUT" : "POST"); selectedMonitor = result; $("#monitor-body").value = JSON.stringify({version: result.version, definition: result.definition}, null, 2); text("#monitor-result", result); await qualityView(); });
  on("#quarantine-first", () => loadQuarantine(0)); on("#quarantine-next", () => nextQuarantine !== null ? loadQuarantine(nextQuarantine) : undefined);
  submit("#quarantine-form", async () => { text("#quarantine-result", await post("/api/quarantine/replay", {event_ids: parse("#quarantine-ids")})); await qualityView(); });

  const localDate = epoch => { if (!epoch) return ""; const value = new Date(epoch * 1000); return new Date(value.getTime() - value.getTimezoneOffset() * 60000).toISOString().slice(0, 16); };
  async function caseworkView() { const previous = $("#case-selector").value; const cases = await api("/api/incidents"); $("#case-selector").innerHTML = '<option value="">선택하세요</option>' + cases.map(row => `<option value="${escapeHtml(row.id)}">${escapeHtml(row.name)} · ${escapeHtml(row.entity)} · ${escapeHtml(row.status)}</option>`).join(""); if (cases.some(row => row.id === previous)) $("#case-selector").value = previous; else { selectedCase = null; $("#case-workspace").hidden = true; } await playbooksView(); }
  async function loadCase(id) { if (!id) { selectedCase = null; $("#case-workspace").hidden = true; return; } const result = await api(`/api/incidents/${enc(id)}/workspace`); if (selectedCase?.incident.id !== id) { selectedRun = null; $("#playbook-review").hidden = true; } selectedCase = result; taskRows = result.tasks; $("#case-selector").value = id; $("#case-workspace").hidden = false; text("#case-heading", `${result.incident.name} · ${result.incident.entity} · ${result.incident.status}`); text("#case-evidence-summary", `필수 작업 ${result.tasks.filter(row => row.mandatory && row.status !== "done").length}개 미완료${result.workspace.overdue ? " · 기한 초과" : ""}`); $("#case-priority").value = result.workspace.priority; $("#case-due").value = localDate(result.workspace.due_at); $("#case-tags").value = result.workspace.tags.join(", "); $("#case-tasks").innerHTML = table(["title", "status", "assignee", "mandatory", "due_at", "action"], result.tasks, {due_at: value => escapeHtml(date(value)), action: (_, row) => `<button data-task="${escapeHtml(row.id)}" data-task-status="${row.status === "done" ? "open" : "done"}">${row.status === "done" ? "다시 열기" : "완료"}</button>`}); $("#case-notes").innerHTML = `<h3>조사 메모 · ${fmt(result.notes_total)}개${result.notes_truncated ? " · 최근 항목만 표시" : ""}</h3>` + table(["at", "actor", "note"], result.notes, {at: value => escapeHtml(date(value))}); $("#case-bookmarks").innerHTML = table(["event_id", "index_name", "label", "actor"], result.bookmarks); await playbooksView(); }
  const caseId = () => { if (!selectedCase) throw Error("사건을 먼저 선택하세요."); return selectedCase.incident.id; };
  async function caseAction(form, action) { const id = caseId(); const result = await post(`/api/incidents/${enc(id)}/actions`, {action, request_id: receipt(form, {id, action})}); finishReceipt(form); text("#case-result", result); await loadCase(id); }
  on("#casework-refresh", async () => { await caseworkView(); if (selectedCase) await loadCase(selectedCase.incident.id); });
  $("#case-selector").onchange = () => loadCase($("#case-selector").value).catch(error => notice(error.message));
  submit("#case-metadata-form", async () => { const id = caseId(); const due = $("#case-due").value; text("#case-result", await post(`/api/incidents/${enc(id)}/workspace`, {version: selectedCase.workspace.version, priority: $("#case-priority").value, due_at: due ? new Date(due).getTime() / 1000 : null, tags: csv("#case-tags")}, "PUT")); await loadCase(id); });
  submit("#case-note-form", async form => { await caseAction(form, {type: "add_note", note: $("#case-note").value}); $("#case-note").value = ""; });
  submit("#case-task-form", async form => { await caseAction(form, {type: "add_task", title: $("#case-task-title").value, assignee: $("#case-task-assignee").value, mandatory: $("#case-task-mandatory").checked}); $("#case-task-title").value = ""; });
  submit("#case-bookmark-form", async () => { const id = caseId(); text("#case-result", await post(`/api/incidents/${enc(id)}/bookmarks`, {event_id: $("#case-event-id").value, label: $("#case-bookmark-label").value})); await loadCase(id); });
  on("#case-export", async () => download(await api(`/api/incidents/${enc(caseId())}/export`), `case-${caseId()}.json`));
  on("#case-open-evidence", async () => { const id = caseId(); await view("intelligence"); await openIncident(id); });
  function newPlaybook() { selectedPlaybook = null; $("#playbook-body").value = JSON.stringify({name: "조사 작업 예제", version: 0, steps: [{id: "task", action: {type: "add_task", title: "근거를 검토하세요", mandatory: true}}]}, null, 2); }
  async function playbooksView() { const [playbooks, response] = await Promise.all([api("/api/playbooks"), api("/api/playbook-runs" + (selectedCase ? "?incident_id=" + enc(selectedCase.incident.id) : ""))]); $("#playbook-list").innerHTML = table(["name", "version", "owner", "updated", "action"], playbooks, {updated: value => escapeHtml(date(value)), action: (_, row) => `<button data-playbook="${escapeHtml(row.id)}">정의 열기</button>`}); const prior = $("#playbook-selector").value; $("#playbook-selector").innerHTML = '<option value="">선택하세요</option>' + playbooks.map(row => `<option value="${escapeHtml(row.id)}">${escapeHtml(row.name)} · v${row.version}</option>`).join(""); if (playbooks.some(row => row.id === prior)) $("#playbook-selector").value = prior; $("#playbook-runs").innerHTML = `<p>${response.truncated ? "최근 실행만 표시합니다." : "현재 권한으로 조회할 수 있는 실행입니다."}</p>` + table(["id", "state", "requested_by", "approved_by", "created", "action"], response.runs, {created: value => escapeHtml(date(value)), action: (_, row) => `<button data-playbook-run="${escapeHtml(row.id)}">실행 검토</button>`}); if (!$("#playbook-body").value) newPlaybook(); }
  async function openRun(id) { const result = await api(`/api/playbook-runs/${enc(id)}`); selectedRun = result; $("#playbook-review").hidden = false; text("#playbook-run-detail", result); $("#playbook-approve").disabled = result.state !== "pending_approval" || result.requested_by === me.name; $("#playbook-cancel").disabled = ["completed", "cancelled", "failed", "unknown"].includes(result.state); }
  on("#playbook-new", newPlaybook);
  submit("#playbook-form", async () => { const result = await post("/api/playbooks" + (selectedPlaybook ? "/" + enc(selectedPlaybook.id) : ""), parse("#playbook-body"), selectedPlaybook ? "PUT" : "POST"); selectedPlaybook = await api(`/api/playbooks/${enc(result.id)}`); $("#playbook-body").value = JSON.stringify({...selectedPlaybook.definition, version: selectedPlaybook.version}, null, 2); text("#playbook-result", result); await playbooksView(); notice("정의만 저장했습니다. 실행 요청과 독립 승인이 따로 필요합니다."); });
  submit("#playbook-start-form", async form => { const incident_id = caseId(); const id = $("#playbook-selector").value; if (!id) throw Error("플레이북을 선택하세요."); const result = await post(`/api/playbooks/${enc(id)}/runs`, {incident_id, request_id: receipt(form, {id, incident_id})}); finishReceipt(form); text("#playbook-result", result); await playbooksView(); await openRun(result.id); });
  on("#playbook-approve", async () => { if (!selectedRun) return; text("#playbook-result", await post(`/api/playbook-runs/${enc(selectedRun.id)}/approve`, {})); await openRun(selectedRun.id); await playbooksView(); });
  on("#playbook-cancel", async () => { if (!selectedRun) return; text("#playbook-result", await post(`/api/playbook-runs/${enc(selectedRun.id)}/cancel`, {})); await openRun(selectedRun.id); await playbooksView(); });
  on("#playbook-run-refresh", async () => { if (selectedRun) await openRun(selectedRun.id); });

  document.addEventListener("click", async event => {
    const button = event.target.closest("button"); if (!button) return;
    try {
      if (button.dataset.contentName) await openContent(button.dataset.contentName);
      if (button.dataset.entityEdit) { const row = await api(`/api/entities/${enc(button.dataset.entityEdit)}`); selectedEntity = row; $("#entity-kind").value = row.kind; $("#entity-name").value = row.name; $("#entity-indexes").value = row.indexes.join(", "); $("#entity-criticality").value = row.criticality; $("#entity-tags").value = row.tags.join(", "); $("#entity-aliases").value = JSON.stringify(row.aliases, null, 2); text("#entity-selected", `${row.name} · version ${row.version}`); }
      if (button.dataset.entityTimeline) await entityTimeline(button.dataset.entityTimeline);
      if (button.dataset.baseline) text("#baseline-result", await api(`/api/behavior/baselines/${enc(button.dataset.baseline)}`));
      if (button.dataset.behaviorRun) text("#baseline-result", await api(`/api/behavior/runs/${enc(button.dataset.behaviorRun)}`));
      if (button.dataset.parser) { const row = parserRows.find(item => item.name === button.dataset.parser); $("#parser-name").value = row.name; $("#parser-version").value = row.version; $("#parser-body").value = JSON.stringify(row.definition, null, 2); }
      if (button.dataset.monitor) { selectedMonitor = monitorRows.find(row => row.id === button.dataset.monitor); $("#monitor-body").value = JSON.stringify({version: selectedMonitor.version, definition: selectedMonitor.definition}, null, 2); }
      if (button.dataset.monitorEvaluate) { text("#monitor-result", await post(`/api/source-monitors/${enc(button.dataset.monitorEvaluate)}/evaluate`, {})); await qualityView(); }
      if (button.dataset.quarantine) text("#quarantine-inspect", quarantineRows.find(row => row.event_id === button.dataset.quarantine));
      if (button.dataset.task) { const task = taskRows.find(row => row.id === button.dataset.task); const id = caseId(); text("#case-result", await post(`/api/incidents/${enc(id)}/tasks/${enc(task.id)}`, {version: task.version, status: button.dataset.taskStatus, assignee: task.assignee, due_at: task.due_at}, "PATCH")); await loadCase(id); }
      if (button.dataset.playbook) { selectedPlaybook = await api(`/api/playbooks/${enc(button.dataset.playbook)}`); $("#playbook-body").value = JSON.stringify({...selectedPlaybook.definition, version: selectedPlaybook.version}, null, 2); $("#playbook-selector").value = selectedPlaybook.id; }
      if (button.dataset.playbookRun) await openRun(button.dataset.playbookRun);
    } catch (error) { notice(error.message); }
  });
}, {once: true});
